const raw = $input.first().json.body ?? $input.first().json ?? {};
const issues = [];
const get = (k, d) => (raw[k] === undefined || raw[k] === null ? d : raw[k]);

const service = String(get('service_name', 'unknown'));
const fault   = String(get('anomaly_type', 'unknown'));
const status  = String(get('status', 'ANOMALY_DETECTED'));
let   score   = Number(get('confidence_score', 0));
const tsRaw   = Number(get('timestamp', Date.now() / 1000));
const tsNum   = Number.isFinite(tsRaw) ? tsRaw : Date.now() / 1000;

if (!raw.service_name) issues.push('service_name missing');
if (!Number.isFinite(score)) { issues.push('confidence_score is not a number'); score = 0; }
if (score < 0 || score > 1) issues.push('confidence_score outside [0,1], clamped');
score = Math.min(Math.max(score, 0), 1);
if (!Number.isFinite(tsRaw)) issues.push('timestamp is not a unix epoch number - defaulted to now');

const ts  = new Date(tsNum * 1000).toISOString();
const pct = (score * 100).toFixed(1);
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const severity = score >= 0.90 ? 'CRITICAL' : score >= 0.75 ? 'HIGH' : 'MEDIUM';
const emoji    = severity === 'CRITICAL' ? '\u{1F534}' : severity === 'HIGH' ? '\u{1F7E0}' : '\u{1F7E1}';
const accent   = severity === 'CRITICAL' ? '#b91c1c'  : severity === 'HIGH'  ? '#c2410c'  : '#a16207';

const rcService = get('root_cause_service', null);
const rcFault   = get('root_cause_fault_type', null);
const rcText    = rcService ? `${rcService} — ${rcFault ?? 'unspecified'}` : 'Investigating…';
const anomalyScore = get('anomaly_score', null);

const EMAIL_TO = 'nourhanelshieikh71@gmail.com';
const SLACK_CHANNEL = '#sentinelas-alerts';

const telegram_html = [
  `${emoji} <b>Sentinelas \u00b7 ${severity}</b>`,
  '',
  `<b>Service:</b> ${esc(service)}`,
  `<b>Type:</b> ${esc(fault)}`,
  `<b>Confidence:</b> ${pct}%`,
  `<b>Status:</b> ${esc(status)}`,
  `<b>Time:</b> ${esc(ts)}`,
  `<b>Root Cause:</b> ${esc(rcText)}`,
].join('\n');

const email_subject = `[Sentinelas ${severity}] ${fault} in ${service} (${pct}%)`;

const rows = [
  ['Service', service], ['Anomaly type', fault], ['Confidence', pct + '%'],
  ['Status', status], ['Root cause', rcText], ['Detected at', ts],
  ['Anomaly score', anomalyScore ?? 'n/a'],
];
const email_html = '<!DOCTYPE html><html><body style="margin:0;padding:24px;background:#f6f7f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif">'
  + '<div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb">'
  + `<div style="background:${accent};padding:16px 20px;color:#fff">`
  + `<div style="font-size:18px;font-weight:700">${emoji} Sentinelas Anomaly Alert</div>`
  + `<div style="font-size:13px;opacity:.9">${esc(severity)} \u00b7 ${pct}% confidence</div></div>`
  + '<div style="padding:20px"><table style="width:100%;border-collapse:collapse;font-size:14px;color:#111827">'
  + rows.map(([k, v]) => `<tr><td style="padding:7px 0;color:#6b7280;width:140px;vertical-align:top">${k}</td>`
                          + `<td style="padding:7px 0"><b>${esc(v)}</b></td></tr>`).join('')
  + '</table></div></div></body></html>';

const email_text = [
  `Sentinelas Anomaly Alert \u2014 ${severity}`, '',
  `Service: ${service}`, `Anomaly type: ${fault}`, `Confidence: ${pct}%`,
  `Status: ${status}`, `Root cause: ${rcText}`, `Detected at: ${ts}`,
  `Anomaly score: ${anomalyScore ?? 'n/a'}`, '',
].join('\n');

// Slack renders mrkdwn, not HTML: *bold* and `code`, plus its own emoji shortcodes.
const slack_emoji = severity === 'CRITICAL' ? ':red_circle:'
                  : severity === 'HIGH'    ? ':large_orange_circle:'
                                           : ':large_yellow_circle:';

const slack_text = [
  `${slack_emoji} *Sentinelas \u00b7 ${severity}*`,
  '',
  `*Service:* \`${service}\``,
  `*Type:* ${fault}`,
  `*Confidence:* ${pct}%`,
  `*Status:* ${status}`,
  `*Time:* ${ts}`,
  `*Root Cause:* ${rcText}`,
].join('\n');

return [{ json: {
  service_name: service, anomaly_type: fault,
  confidence_score: score, confidence_pct: pct,
  severity, severity_emoji: emoji, severity_accent: accent,
  timestamp: ts, status,
  root_cause_service: rcService, root_cause_fault_type: rcFault,
  anomaly_score: anomalyScore,
  payload_issues: issues,
  email_to: EMAIL_TO,
  telegram_html, slack_text, slack_channel: SLACK_CHANNEL,
  email_subject, email_html, email_text,
}}];
